    super.connect()
    await nextFrame()
    this.#startObserver()
    window.addEventListener("resize", this.#windowResized)
  }

  disconnect() {
    super.disconnect()
    this.#stopObserver()
    window.removeEventListener("resize", this.#windowResized)
  }

  notifyBridgeOfVisibilityChange(visible) {
    this.send("visibility", { title: this.#title, elementVisible: visible })
  }

